from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Low-volatility tilting is based on the empirical observation that stocks with lower "
        "volatility tend to outperform those with higher volatility over time."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        symbols = [str(s) for s in view.symbols]
        volatilities: dict[str, float] = {}

        for symbol in symbols:
            if symbol not in history["symbol"].to_list():
                continue
            values = history.filter(pl.col("symbol") == symbol)[
                "adj_close"
            ].drop_nulls().to_list()
            if len(values) < self._window:
                continue

            returns = [(values[i] - values[i - 1]) / values[i - 1] for i in range(1, len(values))]
            volatility = (sum([r**2 for r in returns]) / len(returns)) ** 0.5
            volatilities[symbol] = volatility

        sorted_symbols = [s[0] for s in sorted(volatilities.items(), key=lambda x: x[1])]
        top_n_symbols = sorted_symbols[: min(self._window, len(sorted_symbols))]
        if not top_n_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(top_n_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in top_n_symbols},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
